import sys, statistics
from collections import defaultdict

def summarize(shifts):
    """shifts: list of dicts with keys date, covers, avg_turn_min, eightysix (list), staff."""
    by_day = defaultdict(list)
    for s in shifts:
        by_day[s["date"]].append(s)
    lines = []
    for day, rows in sorted(by_day.items()):
        covers = sum(r["covers"] for r in rows)
        turn = statistics.mean(r["avg_turn_min"] for r in rows)
        out = sorted({i for r in rows for i in r["eightysix"]})
        flag = "SLOW" if turn > 75 else "ok"
        lines.append(f"{day}: covers={covers} avg_turn={turn:.0f}min [{flag}] 86'd={', '.join(out) or '-'}")
    return "\n".join(lines)

